BEGIN;
SELECT pg_advisory_xact_lock(23092026);
-- Run in a Supabase project, inside the transaction generated by npm run db:prepare.
-- Namespaced mt_* tables leave other applications' tables untouched.
CREATE TABLE IF NOT EXISTS public.mt_metadata (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE IF NOT EXISTS public.mt_profiles (
  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  role text NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin'))
);
CREATE OR REPLACE FUNCTION public.mt_create_profile() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  INSERT INTO public.mt_profiles(id) VALUES (NEW.id) ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.mt_create_profile() FROM PUBLIC;
DROP TRIGGER IF EXISTS mt_profile_created ON auth.users;
CREATE TRIGGER mt_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.mt_create_profile();
INSERT INTO public.mt_profiles(id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.mt_is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.mt_profiles WHERE id = (SELECT auth.uid()) AND role = 'admin');
$$;
REVOKE ALL ON FUNCTION public.mt_is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mt_is_admin() TO anon, authenticated;
CREATE TABLE IF NOT EXISTS public.mt_places (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 160),
  type text NOT NULL CHECK (type IN ('restaurant','activity')),
  lat double precision NOT NULL CHECK (lat BETWEEN -90 AND 90),
  lng double precision NOT NULL CHECK (lng BETWEEN -180 AND 180),
  location text NOT NULL CHECK (char_length(location) BETWEEN 1 AND 160),
  description text NOT NULL CHECK (char_length(description) BETWEEN 1 AND 3000),
  description_fr text CHECK (char_length(description_fr) <= 3000),
  rating double precision CHECK (rating BETWEEN 0 AND 5),
  hours text CHECK (char_length(hours) <= 200),
  tags jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(tags) = 'array' AND jsonb_array_length(tags) <= 20),
  image text CHECK (image IS NULL OR image LIKE 'https://%' OR image LIKE '/photos/%'),
  photo_credit jsonb,
  sources jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(sources) = 'array'),
  access text NOT NULL DEFAULT 'unknown' CHECK (access IN ('unknown','open','restricted')),
  published boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.mt_saved_places (
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  place_id bigint NOT NULL REFERENCES public.mt_places(id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('favorites','revisits')),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(user_id,place_id,kind)
);
CREATE INDEX IF NOT EXISTS mt_saved_places_place_idx ON public.mt_saved_places(place_id);
CREATE TABLE IF NOT EXISTS public.mt_rate_limits (
  key text PRIMARY KEY,
  hits integer NOT NULL,
  expires_at timestamptz NOT NULL
);
CREATE OR REPLACE FUNCTION public.mt_check_rate_limit(identifier text, ceiling integer) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE current_hits integer;
BEGIN
  IF identifier !~ '^[a-f0-9]{64}$' OR ceiling < 1 OR ceiling > 100 THEN RAISE EXCEPTION 'Invalid rate limit'; END IF;
  DELETE FROM public.mt_rate_limits WHERE expires_at < now();
  INSERT INTO public.mt_rate_limits(key,hits,expires_at) VALUES(identifier,1,now()+interval '15 minutes')
  ON CONFLICT(key) DO UPDATE SET hits = public.mt_rate_limits.hits + 1
  RETURNING hits INTO current_hits;
  RETURN current_hits <= ceiling;
END;
$$;
REVOKE ALL ON FUNCTION public.mt_check_rate_limit(text,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.mt_check_rate_limit(text,integer) TO service_role;

ALTER TABLE public.mt_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mt_places ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mt_saved_places ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mt_metadata ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mt_rate_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.mt_profiles, public.mt_places, public.mt_saved_places, public.mt_metadata, public.mt_rate_limits FROM anon, authenticated;
GRANT SELECT ON public.mt_places, public.mt_metadata TO anon, authenticated;
GRANT SELECT ON public.mt_profiles TO authenticated;
GRANT INSERT, UPDATE, DELETE ON public.mt_places TO authenticated;
GRANT SELECT, INSERT, DELETE ON public.mt_saved_places TO authenticated;
GRANT USAGE ON SEQUENCE public.mt_places_id_seq TO authenticated;
GRANT ALL ON public.mt_profiles, public.mt_places, public.mt_saved_places, public.mt_metadata, public.mt_rate_limits TO service_role;
GRANT USAGE ON SEQUENCE public.mt_places_id_seq TO service_role;
DROP POLICY IF EXISTS mt_own_profile ON public.mt_profiles;
CREATE POLICY mt_own_profile ON public.mt_profiles FOR SELECT TO authenticated USING (id = (SELECT auth.uid()));
DROP POLICY IF EXISTS mt_read_places ON public.mt_places;
CREATE POLICY mt_read_places ON public.mt_places FOR SELECT TO anon, authenticated USING (published OR (SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_admin_insert ON public.mt_places;
CREATE POLICY mt_admin_insert ON public.mt_places FOR INSERT TO authenticated WITH CHECK ((SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_admin_update ON public.mt_places;
CREATE POLICY mt_admin_update ON public.mt_places FOR UPDATE TO authenticated USING ((SELECT public.mt_is_admin())) WITH CHECK ((SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_admin_delete ON public.mt_places;
CREATE POLICY mt_admin_delete ON public.mt_places FOR DELETE TO authenticated USING ((SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_read_saved ON public.mt_saved_places;
CREATE POLICY mt_read_saved ON public.mt_saved_places FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
DROP POLICY IF EXISTS mt_insert_saved ON public.mt_saved_places;
CREATE POLICY mt_insert_saved ON public.mt_saved_places FOR INSERT TO authenticated WITH CHECK (user_id = (SELECT auth.uid()) AND EXISTS (SELECT 1 FROM public.mt_places WHERE id = place_id AND published));
DROP POLICY IF EXISTS mt_delete_saved ON public.mt_saved_places;
CREATE POLICY mt_delete_saved ON public.mt_saved_places FOR DELETE TO authenticated USING (user_id = (SELECT auth.uid()));
DROP POLICY IF EXISTS mt_public_version ON public.mt_metadata;
CREATE POLICY mt_public_version ON public.mt_metadata FOR SELECT TO anon, authenticated USING (key = 'schema_version');
INSERT INTO public.mt_metadata(key,value) VALUES ('schema_version','1') ON CONFLICT DO NOTHING;


-- Seed once. Re-running setup preserves edits and deliberately deleted places.
DO $seed$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.mt_metadata WHERE key = 'catalogue_seeded') THEN
    INSERT INTO public.mt_places(id,name,type,lat,lng,location,description,description_fr,rating,hours,tags,image,photo_credit,sources,access,published)
    SELECT p.id,p.name,p.type,p.lat,p.lng,p.location,p.description,p.description_fr,p.rating,p.hours,COALESCE(p.tags,'[]'::jsonb),p.image,p.photo_credit,COALESCE(p.sources,'[]'::jsonb),COALESCE(p.access,'unknown'),COALESCE(p.published,true)
    FROM jsonb_to_recordset('[{"id":1,"name":"Le Petibonum","type":"restaurant","lat":14.7015273,"lng":-61.181476,"location":"Le Carbet","description":"A beachfront restaurant in Le Carbet, with Caribbean-inspired cooking and a relaxed setting by the sea.","description_fr":"Un restaurant de plage au Carbet, proposant une cuisine inspirée des produits martiniquais dans un cadre en bord de mer.","tags":["Beachfront","Creole","Seafood","Casual"],"sources":[{"url":"https://petibonum.com/","title":"Le Petibonum","fields":["Name","Town","Description"],"checkedAt":"2026-09-23"},{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/restaurant-le-petibonum","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Map point"],"checkedAt":"2026-09-24"}],"access":"unknown","published":true},{"id":2,"name":"Habitation Clément","type":"activity","lat":14.6019606,"lng":-60.906903,"location":"Le François","description":"A historic estate in Le François with gardens, rum heritage, and contemporary art to explore.","description_fr":"Un domaine historique au François, avec des jardins, le patrimoine du rhum et des expositions d’art contemporain.","hours":"09:00–18:30","tags":["Culture","History","Rum Tasting","Garden"],"image":"/photos/clement.jpg","photo_credit":{"author":"Jeremy Gross","caption":"Habitation Clément · 2014","license":"CC BY-SA 3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Habitation_Cl%C3%A9ment.jpg","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"},"sources":[{"url":"https://www.rhum-clement.com/home/lexperience/","title":"Habitation Clément","fields":["Description","Listed hours"],"checkedAt":"2026-09-23"},{"url":"https://www.martinique.org/fr/que-faire/culture-patrimoine/habitation-clement","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Map point"],"checkedAt":"2026-09-24"}],"access":"unknown","published":true},{"id":3,"name":"Jardin de Balata","type":"activity","lat":14.6721053,"lng":-61.09136,"location":"Fort-de-France","description":"A tropical botanical garden near Fort-de-France, with landscaped paths and treetop walkways.","description_fr":"Un jardin botanique tropical près de Fort-de-France, avec des allées paysagères et des passerelles dans les arbres.","hours":"09:00–18:00 · Last entry / Dernière entrée 16:30","tags":["Nature","Botanical","Family Friendly","Scenic"],"image":"/photos/balata.jpg","photo_credit":{"author":"Box-Off-Dreams, Julie","caption":"Jardin de Balata · 2008","license":"Public domain","sourceUrl":"https://commons.wikimedia.org/wiki/File:Jardin_de_Balata.jpg","licenseUrl":"https://commons.wikimedia.org/wiki/File:Jardin_de_Balata.jpg"},"sources":[{"url":"https://www.jardindebalata.fr/horaires-et-animations","title":"Jardin de Balata","fields":["Name","Town","Listed hours"],"checkedAt":"2026-09-23"},{"url":"https://www.martinique.org/fr/que-faire/sites-naturels-publics/jardin-de-balata","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Map point"],"checkedAt":"2026-09-24"}],"access":"unknown","published":true},{"id":4,"name":"Ti'' Sable","type":"restaurant","lat":14.5066561,"lng":-61.086662,"location":"Les Anses-d''Arlet","description":"A restaurant on Grande Anse beach in Les Anses-d’Arlet. Check service times and reservations with the venue.","description_fr":"Un restaurant sur la plage de Grande Anse, aux Anses-d’Arlet. Consultez le restaurant pour les services et réservations.","tags":["Romantic","Beach","Fine Dining","Sunset View"],"sources":[{"url":"https://www.tisablemartinique.com/en/","title":"Ti Sable","fields":["Name","Town"],"checkedAt":"2026-09-23"},{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/ti-sable","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Map point"],"checkedAt":"2026-09-24"}],"access":"unknown","published":true},{"id":5,"name":"Montagne Pelée","type":"activity","lat":14.8111,"lng":-61.1644,"location":"Le Morne-Rouge","description":"Explore the landscapes of Montagne Pelée on foot. Choose a suitable trail and check access, weather, and conditions before setting out.","description_fr":"Découvrez les paysages de la Montagne Pelée à pied. Choisissez un sentier adapté et vérifiez l’accès, la météo et les conditions avant de partir.","tags":["Hiking","Volcano","Challenge","Nature"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/incontournables/montagne-pelee","title":"Martinique Tourisme","fields":["Name","Description"],"checkedAt":"2026-09-23"}],"access":"unknown","published":true},{"id":6,"name":"Plage des Salines","type":"activity","lat":14.4025,"lng":-60.8758,"location":"Sainte-Anne","description":"A sandy beach in Sainte-Anne, known for its coconut palms and views of the sea.","description_fr":"Une plage de sable à Sainte-Anne, bordée de cocotiers et ouverte sur la mer.","tags":["Beach","Relaxation","Family","Swimming"],"image":"/photos/salines.jpg","photo_credit":{"author":"Hervé NICOLAS","caption":"Salines · 2016","license":"CC BY-SA 4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Etang_des_Salines_(Martinique).jpg","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"sources":[{"url":"https://www.martinique.org/fr/que-faire/sites-naturels-publics/plage-des-salines","title":"Martinique Tourisme","fields":["Name","Town","Description"],"checkedAt":"2026-09-23"}],"access":"unknown","published":true},{"id":7,"name":"Cascade Didier","type":"activity","lat":14.6533,"lng":-61.08,"location":"Fort-de-France","description":"Cascade Didier lies in a drinking-water catchment area. The local tourism guide states that access is prohibited. This listing is not a suggested hiking route.","description_fr":"La cascade Didier se situe dans une zone de captage d’eau potable. Le guide de l’office de tourisme indique que l’accès est interdit. Ce lieu n’est pas proposé comme randonnée.","tags":["Waterfall","Restricted access"],"sources":[{"url":"https://terresducentremartinique.fr/wp-content/uploads/2024/01/CARTE-NATURE-COEUR-DE-MARTINIQUE-2020-1.pdf","title":"Terres du Centre Martinique","fields":["Access restrictions"],"checkedAt":"2026-09-23"}],"access":"restricted","published":true},{"id":8,"name":"Le Zandoli","type":"restaurant","lat":14.555,"lng":-61.052,"location":"Les Trois-Îlets","description":"The gastronomic restaurant at La Suite Villa in Les Trois-Îlets. Contact the venue for current reservations and service times.","description_fr":"Le restaurant gastronomique de La Suite Villa aux Trois-Îlets. Consultez le restaurant pour les réservations et les horaires.","tags":["Fine Dining","Panoramic View","Modern Creole"],"sources":[{"url":"https://la-suite-villa.com/en/restaurant/","title":"La Suite Villa","fields":["Name","Town","Description"],"checkedAt":"2026-09-23"}],"access":"unknown","published":true},{"id":9,"name":"Presqu''île de la Caravelle","type":"activity","lat":14.7726531,"lng":-60.883772,"location":"Tartane","description":"A nature reserve on the Caravelle peninsula, with coastal trails, dry forest, and mangrove landscapes.","description_fr":"Une réserve naturelle sur la presqu’île de la Caravelle, avec des paysages côtiers, de forêt sèche et de mangrove. Vérifiez les conditions d’accès auprès du parc.","tags":["Nature Reserve","Hiking","Coastal","Views"],"sources":[{"url":"https://vr.pnr-martinique.com/caravelle/","title":"Parc naturel de Martinique","fields":["Name"],"checkedAt":"2026-09-23"},{"url":"https://www.martinique.org/fr/que-faire/sites-naturels-publics/reserve-naturelle-de-la-caravelle","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Map point"],"checkedAt":"2026-09-24"}],"access":"unknown","published":true},{"id":10,"name":"Chez Carole","type":"restaurant","lat":14.6067,"lng":-61.0667,"location":"Fort-de-France","description":"A place to discover Creole cooking in the central market area of Fort-de-France.","description_fr":"Un restaurant de cuisine créole dans le secteur du marché de Fort-de-France. Contacte