"Extracurricular","Indoor","Popcorn"],"sources":[{"url":"https://madiana.com/contacts-et-horaires/","title":"Madiana","fields":["Name","Description"],"checkedAt":"2026-09-23"}],"access":"unknown","published":true},{"id":14,"name":"Cinéma Le Rex","type":"activity","lat":14.6038,"lng":-61.0694,"location":"Fort-de-France","description":"This entry from the original catalogue is awaiting verification before publication.","description_fr":"Cette entrée du catalogue initial reste à vérifier avant publication.","tags":["Cinema","Entertainment","Extracurricular","Downtown"],"sources":[],"access":"unknown","published":false},{"id":15,"name":"Plaza Bowling d''Acajou","type":"activity","lat":14.6111,"lng":-61.018,"location":"Le Lamentin","description":"This entry from the original catalogue is awaiting verification before publication.","description_fr":"Cette entrée du catalogue initial reste à vérifier avant publication.","tags":["Bowling","Arcade","Extracurricular","Family Friendly","Nightlife"],"sources":[],"access":"unknown","published":false},{"id":16,"name":"Acro''Kart","type":"activity","lat":14.53487636,"lng":-61.0118258,"location":"Les Trois-Îlets","description":"An outdoor go-karting venue at the Village de la Poterie in Les Trois-Îlets. Check session times and participation requirements.","description_fr":"Une piste de karting aux Trois-Îlets. Vérifiez les horaires des sessions, les réservations et les conditions de participation.","tags":["Karting","Racing Carts","Extracurricular","Adrenaline","Speed"],"sources":[{"url":"https://acrokart.fr/","title":"Acro’Kart","fields":["Name","Description"],"checkedAt":"2026-09-23"},{"url":"https://www.martinique.org/fr/que-faire/sports-et-decouvertes-terre/acrokart-racing-bowling","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Map point"],"checkedAt":"2026-09-24"}],"access":"unknown","published":true},{"id":17,"name":"West Paradise","type":"activity","lat":14.6133,"lng":-61.021,"location":"Le Lamentin","description":"A leisure venue in Le Lamentin with laser games, bowling, and other activities. Check the programme and reservations with the venue.","description_fr":"Un espace de loisirs au Lamentin proposant notamment du laser game et du bowling. Consultez le programme et les réservations du lieu.","tags":["Laser Tag","Bowling","Games","Indoor"],"sources":[{"url":"https://www.westparadise.fr/","title":"West Paradise","fields":["Name","Town","Description"],"checkedAt":"2026-09-23"}],"access":"unknown","published":true},{"id":18,"name":"Hippopotamus La Galleria","type":"restaurant","lat":14.6062,"lng":-61.021,"location":"Le Lamentin","description":"A steakhouse at La Galleria shopping centre in Le Lamentin. Opening hours vary by day.","description_fr":"Un restaurant de grillades au centre commercial La Galleria, au Lamentin. Les horaires varient selon le jour.","tags":["Steakhouse","French","Classy","Burgers","Le Lamentin"],"sources":[{"url":"https://www.hippopotamus.fr/nos-restaurants/hippopotamus-martinique-la-galleria","title":"Hippopotamus","fields":["Name","Town","Description"],"checkedAt":"2026-09-23"}],"access":"unknown","published":true},{"id":19,"name":"Torii Sushi","type":"restaurant","lat":14.6115,"lng":-61.0255,"location":"Le Lamentin","description":"A Japanese restaurant in Jambette Village, Le Lamentin, serving sushi and other Japanese dishes.","description_fr":"Un restaurant japonais à Jambette Village, au Lamentin, proposant des sushis et d’autres spécialités japonaises.","tags":["Sushi","Japanese","Classy","Asian Fusion"],"sources":[{"url":"https://www.martinique.org/fr/bars-restaurants/restaurants/torii-sushi","title":"Martinique Tourisme","fields":["Name","Town","Description"],"checkedAt":"2026-09-23"}],"access":"unknown","published":true},{"id":20,"name":"McDonald''s","type":"restaurant","lat":14.6111,"lng":-61.024,"location":"Le Lamentin","description":"This entry from the original catalogue is awaiting verification before publication.","description_