[{"url":"https://www.martinique.org/fr/que-faire/culture-patrimoine/rhums-baie-des-tresors-habitation-le-galion","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address"],"checkedAt":"2026-09-24"}],"access":"unknown","published":true},{"id":128,"name":"Tropic Reset","type":"activity","lat":14.4989187,"lng":-60.8428213,"location":"Sainte-Luce","description":"An organiser of cultural experiences. Consult the programme for dates and venues. Listed address: Quartier Les Coteaux, 97228. Contact: +596 696 66 23 23.","description_fr":"Un organisateur d’expériences culturelles. Consultez le programme pour les dates et les lieux. Adresse indiquée : Quartier Les Coteaux, 97228. Contact : +596 696 66 23 23.","tags":["Culture","Dance"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/culture-patrimoine/tropic-reset","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address","Telephone"],"checkedAt":"2026-09-24"}],"access":"unknown","published":true},{"id":129,"name":"Coeur Bouliki","type":"activity","lat":14.6832724,"lng":-61.058876,"location":"Saint-Joseph","description":"A forest and riverside recreation site in Saint-Joseph, with space for a picnic and discovering tropical vegetation. Listed address: Quartier Durand, 97212.","description_fr":"Un site de détente forestier et de bord de rivière à Saint-Joseph, pour pique-niquer et découvrir la végétation tropicale. Adresse indiquée : Quartier Durand, 97212.","tags":["Forest","Nature"],"sources":[{"url":"https://www.martinique.org/fr/que-faire/nature-environnement/coeur-bouliki","title":"Comité Martiniquais du Tourisme","fields":["Name","Town","Category","Description","Map point","Address"],"checkedAt":"2026-09-24"}],"access":"unknown","published":true},{"id":130,"name":"Sentier De La Cascade Couleuvre","type":"activity","lat":14.7979608,"lng":-61.221172,"location":"Le Prêcheur","description":"A forest trail f